from taf.ul.ettf.log_analysis.analyzer import SyslogAnalyzer
from taf.ul.ettf.log_analysis.reporter import LogToConsoleAndHtml, LogToFile, PrettyHtmlReporter
from taf.ul.ettf.scheduler.robot_policy_scheduler import Policy
from taf.ul.ettf.scheduler.robot_policy_trigger import Any


NO_ANALYSIS_POLICY = Policy()


SYSLOG_ANALYSIS_POLICY = Policy(
    {
        Any: [
            SyslogAnalyzer()
            .with_reporter(LogToConsoleAndHtml())
            .with_reporter(LogToFile())
            .with_reporter(PrettyHtmlReporter()),
        ],
    }
)
